import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-06-23","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-06-23","date":"2021-06-23T00:00:00.000Z","updated":"2021-06-25T00:00:00.000Z","tags":["distributed storage","Ceph","CRUSH algorithm","high availability","scalability","performance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-06-23.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-06-23.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Crimson_SeaStore_2021-06-23.md"};function l(n,t,s,h,d,g){return a(),r("div",null,[...t[0]||(t[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>PR创建与处理</strong>：Aaron 创建了一个PR来处理同步问题，以实现中断正在运行的命令，如HD和MD测试工具中的C命令，并使用内置的HPV服务器暴露指标。</li><li><strong>Zone设备集成</strong>：讨论了使用zoned和nvme pass-through ioctl以及即将到来的异步ioctl来集成Zone设备的方法。</li><li><strong>调试与构建问题</strong>：讨论了调试构建与发布构建的差异，尤其是调试构建中存在的问题，如无效范围的处理和比较x属性的支持。</li><li><strong>同步与元数据问题</strong>：修复了fretboard中的同步问题，并正在处理PG元数据加载中的分段错误问题。</li><li><strong>性能监控</strong>：尝试通过系统度量基础设施暴露指标，并改进调试设施以更好地处理核心转储问题。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>Zone设备管理</strong>：讨论了使用nvme pass-through ioctl处理Zone设备管理的可行性，以及异步ioctl的潜在优势。</li><li><strong>构建与调试问题</strong>：分析了调试构建中存在的问题，包括无效范围的处理和比较x属性的支持。</li><li><strong>元数据与同步问题</strong>：讨论了fretboard中的同步问题和PG元数据加载中的分段错误问题。</li><li><strong>性能监控与调试设施</strong>：探讨了如何通过系统度量基础设施暴露指标，并改进调试设施以更好地处理核心转储问题。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>Zone设备管理</strong>：决定继续探索nvme pass-through ioctl的使用，并关注异步ioctl的发展。</li><li><strong>构建与调试问题</strong>：决定继续支持比较x属性，并解决调试构建中的问题。</li><li><strong>元数据与同步问题</strong>：决定继续修复fretboard中的同步问题，并处理PG元数据加载中的分段错误问题。</li><li><strong>性能监控与调试设施</strong>：决定改进调试设施，以便更好地处理核心转储问题。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li><strong>Zone设备管理</strong>：继续探索nvme pass-through ioctl的使用，并关注异步ioctl的发展。</li><li><strong>构建与调试问题</strong>：继续支持比较x属性，并解决调试构建中的问题。</li><li><strong>元数据与同步问题</strong>：继续修复fretboard中的同步问题，并处理PG元数据加载中的分段错误问题。</li><li><strong>性能监控与调试设施</strong>：改进调试设施，以便更好地处理核心转储问题。</li></ul><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Aaron</li><li>其他未具名参会者</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了各项议题和后续行动计划后结束，参会人员表示感谢并期待后续的进展。</p>',13)])])}const _=o(i,[["render",l]]);export{u as __pageData,_ as default};
